// Package databases runs one shared server per database engine
// (PostgreSQL, MariaDB, Redis) and gives each app that asks for one
// (run.databases) its own database and user on it, with the connection
// URLs in its environment.
//
// An engine starts the first time an app asks for it and then keeps
// running (Docker restarts it). Engines are on an internal network,
// Network, that apps with databases join: nothing on it is published,
// and it has no route out. Admin passwords and each app's password are
// generated by piway and kept in Dir, mode 0600; apps never get an admin
// password.
package databases

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/ofk0/piway/internal/docker"
	"github.com/ofk0/piway/internal/secrets"
)

// Network is the internal network engines and the apps that use them
// share.
const Network = "piway-db"

// LabelEngine marks an engine's container and volume.
const LabelEngine = "piway.engine"

// readyTimeout bounds an engine's first start, which initialises its
// data directory (MariaDB takes the longest on a Pi).
const readyTimeout = 3 * time.Minute

// Manager starts engines and provisions apps on them.
type Manager struct {
	Docker     *docker.Client
	DockerHost string // for the docker CLI, which runs the clients in the engines
	Dir        string // admin/<engine> and apps/<app>.env passwords
	// OnSD reports whether path is on an SD card; nil asks the kernel.
	OnSD func(path string) bool

	mu sync.Mutex // one engine start or provisioning at a time
}

func (m *Manager) apps() *secrets.Store { return &secrets.Store{Dir: filepath.Join(m.Dir, "apps")} }

// Prepare makes sure each engine in list runs and app has its database
// and user on it, and returns the variables app gets ("NAME=value"). It
// is safe to call on every release.
func (m *Manager) Prepare(ctx context.Context, app string, list []string, out io.Writer) ([]string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if err := m.Docker.EnsureNetwork(ctx, Network, true, map[string]string{LabelEngine: "network"}); err != nil {
		return nil, fmt.Errorf("network %s: %w", Network, err)
	}
	passwords := map[string]string{}
	for _, name := range list {
		e, ok := engines[name]
		if !ok {
			return nil, fmt.Errorf("unknown database %q", name)
		}
		if err := m.ensure(ctx, e, out); err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}
		pw, err := m.appPassword(app, name)
		if err != nil {
			return nil, err
		}
		cmd, stdin := e.provision(app, pw)
		if err := m.exec(ctx, e, cmd, stdin); err != nil {
			return nil, fmt.Errorf("%s: set up %s's database: %w", name, app, err)
		}
		fmt.Fprintf(out, "Database: %s on %s\n", app, containerName(name))
		passwords[name] = pw
	}
	var vars []string
	for _, v := range env(app, list, func(e string) string { return passwords[e] }) {
		vars = append(vars, v.Name+"="+v.Value)
	}
	return vars, nil
}

// Env returns the variables app gets for list, from the passwords stored
// on the last Prepare; ok is false when an engine has not been prepared
// for app yet.
func (m *Manager) Env(app string, list []string) (vars []Var, ok bool, err error) {
	stored, err := m.apps().Values(app)
	if err != nil {
		return nil, false, err
	}
	ok = true
	vars = env(app, list, func(e string) string {
		pw, found := stored[passwordKey(e)]
		ok = ok && found
		return pw
	})
	return vars, ok, nil
}

// ensure starts e unless it runs, creating it the first time, and waits
// until it takes connections.
func (m *Manager) ensure(ctx context.Context, e *engine, out io.Writer) error {
	name := containerName(e.name)
	st, err := m.Docker.Inspect(ctx, name)
	switch {
	case err == nil && st.Running:
		return m.wait(ctx, e, 30*time.Second)
	case err == nil:
		fmt.Fprintf(out, "Starting %s\n", name)
		if err := m.Docker.Start(ctx, name); err != nil {
			return err
		}
		return m.wait(ctx, e, readyTimeout)
	case !errors.Is(err, docker.ErrNotFound):
		return err
	}

	fmt.Fprintf(out, "Starting %s (%s) for the first time\n", name, e.image)
	if ok, err := m.Docker.ImageExists(ctx, e.image); err != nil {
		return err
	} else if !ok {
		fmt.Fprintf(out, "Pulling %s\n", e.image)
		if err := m.Docker.Pull(ctx, e.image); err != nil {
			return err
		}
	}
	vol, err := m.Docker.CreateVolume(ctx, volumeName(e.name), map[string]string{LabelEngine: e.name})
	if err != nil {
		return err
	}
	onSD := m.OnSD
	if onSD == nil {
		onSD = OnSDCard
	}
	sd := onSD(vol.Mountpoint)
	if sd {
		fmt.Fprintf(out, "Its data is on an SD card: tuned for fewer writes (docs/DATABASES.md)\n")
	}
	admin, err := m.adminPassword(e.name)
	if err != nil {
		return err
	}
	id, err := m.Docker.Create(ctx, name, "", docker.Spec{
		Image:       e.image,
		Cmd:         e.cmd(sd),
		Env:         e.env(admin),
		Labels:      map[string]string{LabelEngine: e.name},
		Mounts:      []docker.Mount{{Volume: volumeName(e.name), Target: e.data}},
		MemoryBytes: e.memory,
		Network:     Network,
	})
	if err != nil {
		return err
	}
	if err := m.Docker.Start(ctx, id); err != nil {
		return err
	}
	return m.wait(ctx, e, readyTimeout)
}

// wait polls e's readiness command until it succeeds.
func (m *Manager) wait(ctx context.Context, e *engine, limit time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, limit)
	defer cancel()
	var last error
	for {
		if last = m.exec(ctx, e, e.ready, ""); last == nil {
			return nil
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("not ready after %s: %w", limit, last)
		case <-time.After(time.Second):
		}
	}
}

// exec runs cmd in e's container with stdin, authenticated as admin
// through the environment (the password is never an argument).
func (m *Manager) exec(ctx context.Context, e *engine, cmd []string, stdin string) error {
	admin, err := m.adminPassword(e.name)
	if err != nil {
		return err
	}
	args := append([]string{"exec", "-i", "-e", e.adminEnv, containerName(e.name)}, cmd...)
	c := exec.CommandContext(ctx, "docker", args...)
	c.Env = append(os.Environ(), "DOCKER_HOST="+m.DockerHost, e.adminEnv+"="+admin)
	c.Stdin = strings.NewReader(stdin)
	var outBuf bytes.Buffer
	c.Stdout, c.Stderr = &outBuf, &outBuf
	err = c.Run()
	output := strings.TrimSpace(outBuf.String())
	if err == nil && e.name == "redis" && strings.Contains(output, "ERR") {
		err = errors.New("redis refused a command") // redis-cli exits 0 on errors
	}
	if err != nil {
		if output != "" {
			return fmt.Errorf("%w: %s", err, lastLine(output))
		}
		return err
	}
	return nil
}

// adminPassword returns the engine's admin password, made the first time.
func (m *Manager) adminPassword(engine string) (string, error) {
	store := &secrets.Store{Dir: m.Dir}
	vals, err := store.Values("admin")
	if err != nil {
		return "", err
	}
	key := passwordKey(engine)
	if pw, ok := vals[key]; ok {
		return pw, nil
	}
	pw := newPassword()
	return pw, store.Set("admin", key, pw)
}

// appPassword returns app's password on engine, made the first time.
func (m *Manager) appPassword(app, engine string) (string, error) {
	vals, err := m.apps().Values(app)
	if err != nil {
		return "", err
	}
	key := passwordKey(engine)
	if pw, ok := vals[key]; ok {
		return pw, nil
	}
	pw := newPassword()
	return pw, m.apps().Set(app, key, pw)
}

// newPassword is 32 hex characters: URL- and SQL-safe as is.
func newPassword() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

func lastLine(s string) string {
	lines := strings.Split(s, "\n")
	return strings.TrimSpace(lines[len(lines)-1])
}

// Known reports whether name is an engine piway runs.
func Known(name string) bool { _, ok := engines[name]; return ok }

// Names lists the engines, in a fixed order.
func Names() []string {
	names := make([]string, 0, len(engines))
	for n := range engines {
		names = append(names, n)
	}
	slices.Sort(names)
	return names
}
